import unittest
from candidate import add

class TestAddFunction(unittest.TestCase):
    def test_add_positive_integers(self):
        self.assertEqual(add(2, 3), 5)

    def test_add_large_positive_integers(self):
        self.assertEqual(add(1000000, 2000000), 3000000)

    def test_add_negative_integers(self):
        self.assertEqual(add(-2, -3), -5)

    def test_add_mixed_positive_and_negative(self):
        self.assertEqual(add(-2, 3), 1)

    def test_add_mixed_negative_and_positive(self):
        self.assertEqual(add(3, -2), 1)

    def test_add_zero_and_positive(self):
        self.assertEqual(add(0, 5), 5)

    def test_add_positive_and_zero(self):
        self.assertEqual(add(5, 0), 5)

    def test_add_zero_and_zero(self):
        self.assertEqual(add(0, 0), 0)

    def test_add_zero_and_negative(self):
        self.assertEqual(add(0, -5), -5)

    def test_add_negative_and_zero(self):
        self.assertEqual(add(-5, 0), -5)

    def test_add_floats(self):
        self.assertAlmostEqual(add(2.5, 3.5), 6.0)

    def test_add_negative_floats(self):
        self.assertAlmostEqual(add(-1.5, -2.5), -4.0)

    def test_add_mixed_int_and_float(self):
        self.assertAlmostEqual(add(2, 3.5), 5.5)

    def test_add_mixed_float_and_int(self):
        self.assertAlmostEqual(add(3.5, 2), 5.5)

    def test_add_very_large_numbers(self):
        self.assertEqual(add(10**18, 10**18), 2 * 10**18)

    def test_add_very_small_numbers(self):
        self.assertAlmostEqual(add(1e-10, 1e-10), 2e-10)

    def test_add_boolean_values(self):
        self.assertEqual(add(True, True), 2)

    def test_add_boolean_and_int(self):
        self.assertEqual(add(True, 5), 6)

    def test_add_int_and_boolean(self):
        self.assertEqual(add(5, True), 6)

    def test_add_none_values_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(None, 5)

    def test_add_none_as_second_arg_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(5, None)

    def test_add_both_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(None, None)

    def test_add_missing_arguments_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(1)

    def test_add_no_arguments_raises_type_error(self):
        with self.assertRaises(TypeError):
            add()

    def test_add_extra_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(1, 2, 3)

    def test_add_commutative_property(self):
        self.assertEqual(add(7, 11), add(11, 7))

    def test_add_associative_with_zeros(self):
        self.assertEqual(add(5, add(0, 0)), 5)

    def test_add_identity_element(self):
        for val in [0, 1, -1, 42, -42, 3.14]:
            self.assertAlmostEqual(add(val, 0), val)
            self.assertAlmostEqual(add(0, val), val)

if __name__ == '__main__':
    unittest.main()
